import type { FloatContextType } from "../float.types";

import { useContext, createContext } from "react";

export const FloatContext = createContext<FloatContextType | undefined>(undefined);
export const useFloat = () => {
  const context = useContext(FloatContext);
  if (context === undefined) {
    throw new Error("useFloat must be used within a Float");
  }
  return context;
};
